results.body:
{
  name: dataCollectionRuleName
  location: location
  tags: tags
  kind: 'Linux'
  properties: {
    dataCollectionEndpointId: enableContainerNetworkLogs ? dataCollectionEndpoint.id : null
    dataSources: {
      extensions: [
        {
          name: 'ContainerInsightsExtension'
          streams: streamsWithNetworkLogs
          extensionSettings: {
            dataCollectionSettings: {
              interval: dataCollectionInterval
              namespaceFilteringMode: namespaceFilteringMode
              namespacesForDataCollection: namespacesForDataCollection
              enableContainerLogV2: enableContainerLogV2
            }
          }
          extensionName: 'ContainerInsights'
        }
      ]
    }
    destinations: {
      logAnalytics: [
        {
          workspaceResourceId: logAnalyticsWorkspaceId
          name: 'ciworkspace'
        }
      ]
    }
    dataFlows: [
      {
        streams: streamWithKubeMonAgentEvents
        destinations: [
          'ciworkspace'
        ]
      }
    ]
  }
}

{
  name: dataCollectionRuleName
  location: location
  tags: tags
  kind: 'Linux'
  properties: {
    dataCollectionEndpointId: dataCollectionEndpoint.id
    dataFlows: [
      {
        destinations: ['MonitoringAccount1']
        streams: ['Microsoft-PrometheusMetrics']
      }
    ]
    dataSources: {
      prometheusForwarder: [
        {
          name: 'PrometheusDataSource'
          streams: ['Microsoft-PrometheusMetrics']
          labelIncludeFilter: {}
        }
      ]
    }
    description: 'DCR for Azure Monitor Metrics Profile (Managed Prometheus)'
    destinations: {
      monitoringAccounts: [
        {
          accountResourceId: prometheusWorkspaceId
          name: 'MonitoringAccount1'
        }
      ]
    }
  }
}

